package main
import("context";"errors";"log/slog";"net/http";"os";"os/signal";"syscall";"time";"github.com/aqaaab/cinema/services/api/internal/httpapi")
func main(){addr:=os.Getenv("ADDR");if addr==""{addr=":8080"};srv:=&http.Server{Addr:addr,Handler:httpapi.New(),ReadHeaderTimeout:5*time.Second,ReadTimeout:15*time.Second,WriteTimeout:20*time.Second,IdleTimeout:60*time.Second,MaxHeaderBytes:1<<20};ctx,stop:=signal.NotifyContext(context.Background(),os.Interrupt,syscall.SIGTERM);defer stop();errCh:=make(chan error,1);go func(){slog.Info("Cinema API listening","addr",addr);if e:=srv.ListenAndServe();e!=nil&&!errors.Is(e,http.ErrServerClosed){errCh<-e}}();select{case e:=<-errCh:if e!=nil{slog.Error("server failed","error",e);os.Exit(1)};case <-ctx.Done():c,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();if e:=srv.Shutdown(c);e!=nil{slog.Error("shutdown failed","error",e);_ = srv.Close();os.Exit(1)}}}
